-- Generic Markdown renderer glyph fallback. The table is generated by the
-- same bundled-font coverage code used by note snapshots; body fonts here
-- remain the generic renderer's DejaVu faces.
local GLYPHS = {
  fallback = {},
  serif_uncovered = {},
  sans_uncovered = {},
  mono_uncovered = {},
}
local FE0F = "\239\184\143"

local function load_glyph_table(path)
  if not path or path == "" then return end
  local ok, table_value = pcall(dofile, path)
  if not ok or type(table_value) ~= "table" then return end
  for cp, value in pairs(table_value) do
    if type(cp) == "number" and value then GLYPHS.fallback[cp] = true end
  end
  for _, name in ipairs({ "serif_uncovered", "sans_uncovered", "mono_uncovered" }) do
    local role = table_value[name]
    if type(role) == "table" then
      for cp, value in pairs(role) do
        if type(cp) == "number" and value then GLYPHS[name][cp] = true end
      end
    end
  end
end

local function strip_fe0f(text)
  return (text:gsub(FE0F, ""))
end

local function kind_for_text(cp)
  if GLYPHS.fallback[cp] then return "fallback" end
  if GLYPHS.serif_uncovered[cp] then
    if not GLYPHS.mono_uncovered[cp] then return "mono" end
    if not GLYPHS.sans_uncovered[cp] then return "sans" end
    return "fallback"
  end
  return nil
end

local function kind_for_code(cp)
  if GLYPHS.fallback[cp] then return "fallback" end
  if GLYPHS.mono_uncovered[cp] then
    if not GLYPHS.serif_uncovered[cp] then return "serif" end
    if not GLYPHS.sans_uncovered[cp] then return "sans" end
  end
  return nil
end

local WRAPPERS = {
  fallback = { "\\BobFallbackBegin{}", "\\BobFallbackEnd{}" },
  mono = { "\\BobMonoGlyphBegin{}", "\\BobMonoGlyphEnd{}" },
  sans = { "\\BobSansGlyphBegin{}", "\\BobSansGlyphEnd{}" },
  serif = { "\\BobSerifGlyphBegin{}", "\\BobSerifGlyphEnd{}" },
}

local function raw(text)
  return pandoc.RawInline("latex", text)
end

local function wrap_text(text, is_code, code_attr)
  text = strip_fe0f(text)
  local out = {}
  local buffer = {}
  local current_kind = nil

  local function flush()
    if #buffer == 0 then return end
    local chunk = table.concat(buffer)
    buffer = {}
    if current_kind then
      local wrappers = WRAPPERS[current_kind]
      out[#out + 1] = raw(wrappers[1])
      out[#out + 1] = pandoc.Str(chunk)
      out[#out + 1] = raw(wrappers[2])
    elseif is_code then
      out[#out + 1] = pandoc.Code(chunk, code_attr)
    else
      out[#out + 1] = pandoc.Str(chunk)
    end
  end

  for _, cp in utf8.codes(text) do
    local kind = is_code and kind_for_code(cp) or kind_for_text(cp)
    if kind ~= current_kind then
      flush()
      current_kind = kind
    end
    buffer[#buffer + 1] = utf8.char(cp)
  end
  flush()
  return out
end

function Pandoc(doc)
  if not FORMAT:match("latex") then return nil end
  local path = doc.meta["bob-glyph-table"]
  if path and path.t == "MetaString" then path = path.text end
  load_glyph_table(path)

  doc.blocks = doc.blocks:walk({
    Str = function(el)
      local wrapped = wrap_text(el.text, false)
      if #wrapped == 1 and wrapped[1].t == "Str" and wrapped[1].text == el.text then
        return nil
      end
      return wrapped
    end,
    Code = function(el)
      local wrapped = wrap_text(el.text, true, el.attr)
      if #wrapped == 1 and wrapped[1].t == "Code" and wrapped[1].text == el.text then
        return nil
      end
      return wrapped
    end,
  })
  return doc
end
